func fragOf(op, col uint32) runtime.Frag {
	// Bounded by the table, not nCols: existence pseudo-columns live past
	// the real ones. Order, ident and arena lookups stay nCols-bounded,
	// so a pseudo-column can never be ordered by, cursored on, or bound.
	if int(col) >= len(fragTable) || int(op) >= len(fragTable[0]) {
		return runtime.Frag{}
	}
	return fragTable[col][op]
}

// defaultOrder is what a query with no Order() uses.
//
// It is never empty. A read without ORDER BY has no defined order, so
// paging one is a bug waiting for a plan change to expose it — and the
// primary key is the cheapest total order available.
var defaultOrder = [2]runtime.Tok{
	runtime.MakeOrder(runtime.Asc, 0), // hostname
	runtime.MakeOrder(runtime.Asc, 1), // bucket
}

var (
	cache       = runtime.NewTreeCache()
	offsetCache = runtime.NewTreeCache()
	countCache  = runtime.NewTreeCache()
	existsCache = runtime.NewTreeCache()
)

// Shapes reports how many distinct query structures have compiled.
// `storm lint` uses it to catch a builder minting a statement per request.
func Shapes() int { return cache.Shapes() }

// ShapeFlushes reports how many times a shape cache in this package hit
// runtime.ShapeCap and dropped. Zero is the expected value forever:
// nonzero means a call site is minting structures from request data
// rather than from code, and the fix is that call site, not a bigger
// cap. Export it as a gauge — it is the cheapest early warning that a
// filter screen turned into 2^n statements.
func ShapeFlushes() int {
	return cache.Flushes() + offsetCache.Flushes() +
		countCache.Flushes() + existsCache.Flushes() +
		updAllCache.Flushes() + delAllCache.Flushes()
}

// stmtFor compiles a read. LIMIT and LIMIT/OFFSET are different
// statements with different placeholder counts, so they get different
// caches rather than a sentinel token muddying the key.
func stmtFor(toks []runtime.Tok, withOffset bool, lock uint8) *runtime.Stmt {
	i, suffix := 0, limitSuffix
	if withOffset {
		i, suffix = 1, limitOffsetSuffix
	}
	c := lockCaches[lock][i]
	suffix += lockSuffix[lock]
	if st := c.Get(toks); st != nil {
		return st
	}
	return c.Put(toks, runtime.SpliceTree(selectPrefix, toks, lowering, suffix))
}

// existsStmtFor compiles the existence probe: SELECT 1, no ORDER BY,
// LIMIT 1 — the planner stops at the first matching tuple instead of
// sorting every match to return the "first" of an order nobody reads.
func existsStmtFor(toks []runtime.Tok) *runtime.Stmt {
	if st := existsCache.Get(toks); st != nil {
		return st
	}
	return existsCache.Put(toks, runtime.SpliceTree(existsPrefix, toks, lowering, existsSuffix))
}

func countStmtFor(toks []runtime.Tok) *runtime.Stmt {
	if st := countCache.Get(toks); st != nil {
		return st
	}
	// A count ignores ordering as well as LIMIT: ordering a scalar is
	// wasted work, and the token stream is trimmed before it gets here.
	return countCache.Put(toks, runtime.SpliceTree(countPrefix, toks, lowering, ""))
}

// Composition seams, for the generated CONTEXT package and it alone:
// cross-table statements (a filtered semi-join spans two packages) are
// assembled there from each side's tokens, fragments and bindings. Ids
// only — no SQL text and no value crosses here.

// FragOf is the compiled fragment table, exported for composition.
func FragOf(op, col uint32) runtime.Frag { return fragOf(op, col) }

// Lowering is this package's back-end text, exported for composition.
func Lowering() runtime.Lowering { return lowering }

// StmtPieces are the statement's constant parts, exported for composition.
func StmtPieces() (selectPfx, countPfx, limitSfx string) {
	return selectPrefix, countPrefix, limitSuffix
}

// PredToks appends this query's predicate stream to dst: top-level
// conjuncts reduced to one entry, order excluded.
func (q Query) PredToks(dst []runtime.Tok) []runtime.Tok {
	var buf [21]runtime.Tok
	return append(dst, q.preds(&buf)...)
}

// OrderToks appends this query's ordering — explicit, or the default
// unless Unordered.
func (q Query) OrderToks(dst []runtime.Tok) []runtime.Tok {
	if q.no == 0 {
		if q.noOrder {
			return dst
		}
		return append(dst, defaultOrder[:]...)
	}
	return append(dst, q.otoks[:q.no]...)
}

// BindPreds binds this query's predicate values into b, appending to v.
func (q Query) BindPreds(b *Binder, v []any) []any {
	return append(v, q.bindPreds(b)...)
}

// BindPaging appends the LIMIT (and OFFSET when set) arguments.
func (q Query) BindPaging(b *Binder, v []any) []any {
	b.limit = q.limit
	v = append(v, &b.limit)
	if q.offset > 0 {
		b.offset = q.offset
		v = append(v, &b.offset)
	}
	return v
}

// Shape is a fingerprint of this query's structure — equal shapes share a
// compiled statement. Values do not contribute, which is the point.
func (q Query) Shape() uint64 {
	var buf [21]runtime.Tok
	return runtime.HashToks(q.stream(&buf))
}

// SQL returns the compiled text for this query's structure.
func (q Query) SQL() string {
	var buf [21]runtime.Tok
	return stmtFor(q.stream(&buf), q.offset > 0, q.lock).SQL
}

// Scan decodes one row from raw wire bytes into r, copying text into sl.
//
// Exported for the context package, which assembles batched results and
// therefore has to decode rows it did not issue the query for.
func Scan(rv [][]byte, r *Row, sl *runtime.Slab) error { return scan(rv, r, sl) }

// scan decodes one row straight from the wire. No reflect, no `any`, no
// driver.Value: the generator knows every column's type already.
//
// It returns an error only for a value the Go type cannot carry — a
// numeric past 18 significant digits, or a NaN. Those must not become a
// plausible zero, and a row scanner is the last place that can tell.
func scan(rv [][]byte, r *Row, sl *runtime.Slab) error {
	r.Hostname = sl.Str(rv[0])
	r.Bucket = runtime.Timestamptz(rv[1])
	r.Samples = runtime.Int4(rv[2])
	r.CpuSum = runtime.Float8(rv[3])
	r.CpuN = runtime.Int4(rv[4])
	r.CpuMax = runtime.Nullable(rv[5], runtime.Float4)
	r.MemPct = runtime.Nullable(rv[6], runtime.Float4)
	r.SwapPct = runtime.Nullable(rv[7], runtime.Float4)
	r.Disks = runtime.NullJSON(rv[8], sl)
	r.RxSum = runtime.Float8(rv[9])
	r.TxSum = runtime.Float8(rv[10])
	r.NetN = runtime.Int4(rv[11])
	r.RxMax = runtime.Nullable(rv[12], runtime.Float8)
	r.TxMax = runtime.Nullable(rv[13], runtime.Float8)
	return nil
}

type binder struct {
	vals   []any
	strs   [6]string
	nums   [6]int64
	tims   [4]time.Time
	f64s   [4]float64
	jsns   [2]runtime.JSON
	anyStr [3][]string
	anyI32 [3][]int32
	limit  int64
	offset int64
}

var binders = runtime.NewPool(func() *binder {
	return &binder{vals: make([]any, 0, 17)}
})

// Binder is the pooled argument buffer.
type Binder = binder

func GetBinder() *Binder  { return binders.Get() }
func PutBinder(b *Binder) { putBinder(b) }

// putBinder clears every field that references memory OUTSIDE the binder
// before pooling it. A pooled binder otherwise PINS the caller's data —
// the slice behind an In(...) and the bytes behind every bound string —
// for as long as the pool holds it, which is forever. The numeric, time
// and uuid arenas are value arrays and pin nothing; vals points at the
// binder's own fields. A few nil stores against a round trip is free.
func putBinder(b *binder) {
	for i := range b.strs {
		b.strs[i] = ""
	}
	for i := range b.anyStr {
		b.anyStr[i] = nil
	}
	for i := range b.anyI32 {
		b.anyI32[i] = nil
	}
	binders.Put(b)
}

// bindPreds copies arena values into the pooled buffer and points the
// []any at the buffer's own fields — boxing a pointer does not allocate.
// Count and Exists stop here: their statements carry no LIMIT or OFFSET.
func (q Query) bindPreds(b *binder) []any {
	v := b.vals[:0]
	var ns, nn, ntm, nf, njs, nas, nai32 uint8
	for i := uint8(0); i < q.nt; i++ {
		t := q.toks[i]
		// KLeaf binds a predicate's value; KCol binds a keyset cursor's.
		// Both live in the same per-type arenas in stream order, so the
		// column switch below handles them identically. A KCol carries no
		// operator — its op is opNone, which matches no case in the
		// operator switch and falls straight through.
		if k := t.Kind(); k != runtime.KLeaf && k != runtime.KCol {
			continue
		}
		switch runtime.Op(t.Op()) {
		case opIsNull, opIsNotNull:
			continue
		case opIn, opNotIn, opArrayContains, opArrayContainedBy, opArrayOverlaps, opHasAnyKey, opHasAllKeys:
			switch t.Col() {
			case 0:
				b.anyStr[nas] = q.anyStr[nas]
				v = append(v, &b.anyStr[nas])
				nas++
			case 2:
				b.anyI32[nai32] = q.anyI32[nai32]
				v = append(v, &b.anyI32[nai32])
				nai32++
			case 4:
				b.anyI32[nai32] = q.anyI32[nai32]
				v = append(v, &b.anyI32[nai32])
				nai32++
			case 8:
				b.anyStr[nas] = q.anyStr[nas]
				v = append(v, &b.anyStr[nas])
				nas++
			case 11:
				b.anyI32[nai32] = q.anyI32[nai32]
				v = append(v, &b.anyI32[nai32])
				nai32++
			}
			continue
		}
		switch t.Col() {
		case 0:
			b.strs[ns] = q.strs[ns]
			v = append(v, &b.strs[ns])
			ns++
		case 1:
			b.tims[ntm] = q.tims[ntm]
			v = append(v, &b.tims[ntm])
			ntm++
		case 2:
			b.nums[nn] = q.nums[nn]
			v = append(v, &b.nums[nn])
			nn++
		case 3:
			b.f64s[nf] = q.f64s[nf]
			v = append(v, &b.f64s[nf])
			nf++
		case 4:
			b.nums[nn] = q.nums[nn]
			v = append(v, &b.nums[nn])
			nn++
		case 5:
			b.f64s[nf] = q.f64s[nf]
			v = append(v, &b.f64s[nf])
			nf++
		case 6:
			b.f64s[nf] = q.f64s[nf]
			v = append(v, &b.f64s[nf])
			nf++
		case 7:
			b.f64s[nf] = q.f64s[nf]
			v = append(v, &b.f64s[nf])
			nf++
		case 8:
			b.jsns[njs] = q.jsns[njs]
			v = append(v, &b.jsns[njs])
			njs++
		case 9:
			b.f64s[nf] = q.f64s[nf]
			v = append(v, &b.f64s[nf])
			nf++
		case 10:
			b.f64s[nf] = q.f64s[nf]
			v = append(v, &b.f64s[nf])
			nf++
		case 11:
			b.nums[nn] = q.nums[nn]
			v = append(v, &b.nums[nn])
			nn++
		case 12:
			b.f64s[nf] = q.f64s[nf]
			v = append(v, &b.f64s[nf])
			nf++
		case 13:
			b.f64s[nf] = q.f64s[nf]
			v = append(v, &b.f64s[nf])
			nf++
		}
	}
	b.vals = v
	return v
}

// bind is bindPreds plus the paging arguments, in suffix order.
func (q Query) bind(b *binder) []any {
	v := q.bindPreds(b)
	b.limit = q.limit
	v = append(v, &b.limit)
	// An offset of zero is absent from the statement, so binding it
	// would leave an argument nothing consumes.
	if q.offset > 0 {
		b.offset = q.offset
		v = append(v, &b.offset)
	}
	b.vals = v
	return v
}

// All runs the query and decodes every row.
func (q Query) All(ctx context.Context, ex runtime.Executor, dst []Row) ([]Row, error) {
	var sl runtime.Slab
	return q.AllInto(ctx, ex, dst, &sl)
}

// AllInto lets the caller own the string arena.
func (q Query) AllInto(ctx context.Context, ex runtime.Executor, dst []Row, sl *runtime.Slab) ([]Row, error) {
	if err := q.Err(); err != nil {
		return dst, err
	}
	var buf [21]runtime.Tok
	st := stmtFor(q.stream(&buf), q.offset > 0, q.lock)
	if st.Err != nil {
		// A malformed token stream is a code-generation bug. Executing it
		// would run a query whose filter is not the one that was asked for.
		return dst, st.Err
	}
	sl.Reserve(st.SlabHint())
	b := binders.Get()
	defer putBinder(b)

	rows, err := ex.Query(ctx, st.SQL, q.bind(b))
	if err != nil {
		return dst, err
	}
	defer rows.Close()
	for rows.Next() {
		dst = append(dst, Row{})
		if err := scan(rows.RawValues(), &dst[len(dst)-1], sl); err != nil {
			return dst, err
		}
	}
	st.ObserveSlab(sl.Size())
	return dst, rows.Err()
}

// One returns the first row, if any.
func (q Query) One(ctx context.Context, ex runtime.Executor) (Row, bool, error) {
	var sl runtime.Slab
	var buf [1]Row
	out, err := q.Limit(1).AllInto(ctx, ex, buf[:0], &sl)
	if err != nil || len(out) == 0 {
		return Row{}, false, err
	}
	return out[0], true, nil
}

// Count ignores Limit: counting a truncated set is a bug, not a feature.
func (q Query) Count(ctx context.Context, ex runtime.Executor) (int64, error) {
	if err := q.Err(); err != nil {
		return 0, err
	}
	if q.lock != 0 {
		return 0, errCountLocked
	}
	var buf [21]runtime.Tok
	st := countStmtFor(q.preds(&buf))
	if st.Err != nil {
		// A malformed token stream is a code-generation bug. Executing it
		// would run a query whose filter is not the one that was asked for.
		return 0, st.Err
	}
	b := binders.Get()
	defer putBinder(b)
	// bindPreds, not bind: a count has no LIMIT and no OFFSET. The old
	// form bound everything and sliced the last argument off, which was
	// the limit — unless Offset was set, in which case it silently kept
	// the limit and dropped the offset, and the statement mismatched.
	rows, err := ex.Query(ctx, st.SQL, q.bindPreds(b))
	if err != nil {
		return 0, err
	}
	defer rows.Close()
	var n int64
	if rows.Next() {
		n = runtime.Int8(rows.RawValues()[0])
	}
	return n, rows.Err()
}

// Exists asks the one-bit question with a one-bit statement: SELECT 1,
// no ORDER BY, LIMIT 1. It was previously One() with the row thrown
// away, which projected every column AND carried the default ordering —
// measured on 50k rows, the planner top-N-sorted all 16,667 matches to
// return the "first" of an order nobody was going to read.
func (q Query) Exists(ctx context.Context, ex runtime.Executor) (bool, error) {
	if err := q.Err(); err != nil {
		return false, err
	}
	if q.lock != 0 {
		return false, errExistsLocked
	}
	var buf [21]runtime.Tok
	st := existsStmtFor(q.preds(&buf))
	if st.Err != nil {
		return false, st.Err
	}
	b := binders.Get()
	defer putBinder(b)
	rows, err := ex.Query(ctx, st.SQL, q.bindPreds(b))
	if err != nil {
		return false, err
	}
	defer rows.Close()
	return rows.Next(), rows.Err()
}

// Prepare resolves the structure and binds arguments without executing.
func (q Query) Prepare(b *Binder) (string, []any) {
	var buf [21]runtime.Tok
	return stmtFor(q.stream(&buf), q.offset > 0, q.lock).SQL, q.bind(b)
}

