//	"net_n" = "usage_history"."net_n" + EXCLUDED."net_n"
//
// The sum is the database's, in the same statement, so two writers
// counting into one row both land. Reading the row, adding in Go and
// upserting the total loses one of them, with nothing to show it.
// Without an OnConflict target, or with DoNothing, it is SetNetN.
func (n *Ins) AddNetNOnConflict(v int32) {
	n.row.NetN = v
	n.set |= iNetN
	n.add |= iNetN
}

func (n *Ins) SetRxMax(v float64) {
	n.row.RxMax = runtime.Null[float64]{V: v, Valid: true}
	n.set |= iRxMax
}

// SetRxMaxNull writes SQL NULL explicitly, which is not the same as
// leaving the column unset and taking its default.
func (n *Ins) SetRxMaxNull() {
	n.row.RxMax = runtime.Null[float64]{}
	n.set |= iRxMax
}

func (n *Ins) SetTxMax(v float64) {
	n.row.TxMax = runtime.Null[float64]{V: v, Valid: true}
	n.set |= iTxMax
}

// SetTxMaxNull writes SQL NULL explicitly, which is not the same as
// leaving the column unset and taking its default.
func (n *Ins) SetTxMaxNull() {
	n.row.TxMax = runtime.Null[float64]{}
	n.set |= iTxMax
}

// The conflict encoding. One byte holds both which unique index an
// upsert names and what it does on collision, so the insert statement
// cache stays keyed by one mask and one byte:
//
//	0        no ON CONFLICT clause
//	1        ON CONFLICT DO NOTHING, on any unique index
//	2+2*i    target i, DO UPDATE
//	3+2*i    target i, DO NOTHING
const conflictAny = 1

// upsertTail builds the ON CONFLICT clause for one encoded conflict
// and one insert mask.
//
// The mask is what makes an upsert correct: it overwrites only the
// columns the caller ASSIGNED. Assigning every column would revert
// each one the caller left out to its default, on the row that
// already exists — a silent data loss that reads as an upsert working.
//
// add marks the assigned columns that ACCUMULATE instead: the row
// that already exists keeps its value plus the one this insert
// carried. See the Add…OnConflict setters.
func upsertTail(conflict uint8, mask uint64, add uint64) string {
	if conflict == conflictAny {
		return " ON CONFLICT DO NOTHING"
	}
	spec, i := conflictSpecs[(conflict-2)/2], (conflict-2)/2
	if conflict%2 == 1 {
		return spec + " DO NOTHING"
	}
	set := assignable(i, mask)
	if len(set) == 0 {
		// Nothing to overwrite. DO UPDATE SET with an empty list is not
		// SQL, and leaving the row alone is what the caller asked for.
		return spec + " DO NOTHING"
	}
	return spec + " DO UPDATE SET " + joinAssign(set, add)
}

// conflictSpecs is one inference specification per target, in
// declaration order. A PARTIAL unique index carries its predicate:
// PostgreSQL infers the index from the keys and the predicate
// together, and without it the insert fails at run time — on the first
// row that collides, which a test inserting distinct rows never sees.
var conflictSpecs = []string{
	" ON CONFLICT (\"hostname\", \"bucket\")",
}

// assignable is the columns target i may overwrite, given the mask.
func assignable(i uint8, mask uint64) []string {
	set := make([]string, 0, 12)
	switch i {
	case 0:
		if mask&(1<<2) != 0 {
			set = append(set, "samples")
		}
		if mask&(1<<3) != 0 {
			set = append(set, "cpu_sum")
		}
		if mask&(1<<4) != 0 {
			set = append(set, "cpu_n")
		}
		if mask&(1<<5) != 0 {
			set = append(set, "cpu_max")
		}
		if mask&(1<<6) != 0 {
			set = append(set, "mem_pct")
		}
		if mask&(1<<7) != 0 {
			set = append(set, "swap_pct")
		}
		if mask&(1<<8) != 0 {
			set = append(set, "disks")
		}
		if mask&(1<<9) != 0 {
			set = append(set, "rx_sum")
		}
		if mask&(1<<10) != 0 {
			set = append(set, "tx_sum")
		}
		if mask&(1<<11) != 0 {
			set = append(set, "net_n")
		}
		if mask&(1<<12) != 0 {
			set = append(set, "rx_max")
		}
		if mask&(1<<13) != 0 {
			set = append(set, "tx_max")
		}
	}
	return set
}

// OnConflictHostnameBucket upserts on the unique index over (hostname, bucket).
//
// The row that already exists keeps every column this insert did
// not assign. Follow with DoNothing() to leave it untouched
// entirely.
func (n *Ins) OnConflictHostnameBucket() *Ins {
	n.conflict = 2
	return n
}

// DoNothing makes the insert a no-op when the row is already there —
// the idempotent insert, and the commonest upsert there is.
//
// On its own it names no index, so ANY unique violation is the no-op:
//
//	n.DoNothing()                  // ON CONFLICT DO NOTHING
//	n.OnConflictHostnameBucket().DoNothing()  // only on that one index
//
// Insert then returns runtime.ErrNoRows when nothing was written,
// because DO NOTHING suppresses the RETURNING row: there is no row to
// return, and reporting a zero-valued one as inserted would be a lie.
func (n *Ins) DoNothing() *Ins {
	if n.conflict < 2 {
		n.conflict = conflictAny
		return n
	}
	n.conflict |= 1
	return n
}

// joinAssign renders the DO UPDATE SET list for the columns the caller
// assigned. The punctuation comes from the back end, never from here.
func joinAssign(set []string, add uint64) string {
	out := ""
	for i, c := range set {
		if i > 0 {
			out += ", "
		}
		if a, ok := assignAdded(c, add); ok {
			out += a
			continue
		}
		out += assignExcluded(c)
	}
	return out
}

// assignAdded is the accumulating assignment for column c, when the
// caller asked for one: the existing row's value plus the rejected
// row's, added by the database in the same statement, so two
// concurrent upserts both land rather than one overwriting the other.
func assignAdded(c string, add uint64) (string, bool) {
	switch c {
	case "samples":
		return "\"samples\" = \"usage_history\".\"samples\" + EXCLUDED.\"samples\"", add&iSamples != 0
	case "cpu_sum":
		return "\"cpu_sum\" = \"usage_history\".\"cpu_sum\" + EXCLUDED.\"cpu_sum\"", add&iCpuSum != 0
	case "cpu_n":
		return "\"cpu_n\" = \"usage_history\".\"cpu_n\" + EXCLUDED.\"cpu_n\"", add&iCpuN != 0
	case "rx_sum":
		return "\"rx_sum\" = \"usage_history\".\"rx_sum\" + EXCLUDED.\"rx_sum\"", add&iRxSum != 0
	case "tx_sum":
		return "\"tx_sum\" = \"usage_history\".\"tx_sum\" + EXCLUDED.\"tx_sum\"", add&iTxSum != 0
	case "net_n":
		return "\"net_n\" = \"usage_history\".\"net_n\" + EXCLUDED.\"net_n\"", add&iNetN != 0
	}
	return "", false
}

var assignFor = map[string]string{
	"samples":  "\"samples\" = EXCLUDED.\"samples\"",
	"cpu_sum":  "\"cpu_sum\" = EXCLUDED.\"cpu_sum\"",
	"cpu_n":    "\"cpu_n\" = EXCLUDED.\"cpu_n\"",
	"cpu_max":  "\"cpu_max\" = EXCLUDED.\"cpu_max\"",
	"mem_pct":  "\"mem_pct\" = EXCLUDED.\"mem_pct\"",
	"swap_pct": "\"swap_pct\" = EXCLUDED.\"swap_pct\"",
	"disks":    "\"disks\" = EXCLUDED.\"disks\"",
	"rx_sum":   "\"rx_sum\" = EXCLUDED.\"rx_sum\"",
	"tx_sum":   "\"tx_sum\" = EXCLUDED.\"tx_sum\"",
	"net_n":    "\"net_n\" = EXCLUDED.\"net_n\"",
	"rx_max":   "\"rx_max\" = EXCLUDED.\"rx_max\"",
	"tx_max":   "\"tx_max\" = EXCLUDED.\"tx_max\"",
}

func assignExcluded(c string) string { return assignFor[c] }

func stmtForInsert(mask uint64, conflict uint8, add uint64) *runtime.Stmt {
	// The conflict clause is part of the statement, so it must be part of
	// the key. Packing it above the column bits keeps one cache for both.
	key := mask | uint64(conflict)<<nInsertable
	// Accumulating only means something in a DO UPDATE (an even code
	// from 2): anywhere else it is an ordinary insert of the value, and
	// keying it apart would compile the same statement twice.
	if conflict < 2 || conflict%2 == 1 {
		add = 0
	}
	add &= mask
	if st := insCache.Get(runtime.MaskKey{Dirty: key, Expr: add}); st != nil {
		return st
	}
	cols := make([]string, 0, nInsertable)
	for i := 0; i < nInsertable; i++ {
		if mask&(1<<uint(i)) != 0 {
			cols = append(cols, insCols[i])
		}
	}
	suffix := insReturning
	if conflict > 0 {
		suffix = upsertTail(conflict, mask, add) + insReturning
	}
	return insCache.Put(runtime.MaskKey{Dirty: key, Expr: add}, runtime.SpliceInsertWith(insPrefix, insParts, cols, insPlaceholder, suffix))
}

// Insert writes the assigned columns and reads every column back, so
// database-computed values land in the returned Row rather than needing a
// second SELECT that would race every other writer.
func (n *Ins) Insert(ctx context.Context, ex runtime.Executor) (Row, error) {
	if n.set == 0 {
		return Row{}, runtime.ErrNothingAssigned
	}
	st := stmtForInsert(n.set, n.conflict, n.add)
	if st.Err != nil {
		// A malformed token stream is a code-generation bug. Executing it
		// would run a query whose filter is not the one that was asked for.
		return Row{}, st.Err
	}
	args := make([]any, 0, st.NArg)
	for i := 0; i < nInsertable; i++ {
		if n.set&(1<<uint(i)) == 0 {
			continue
		}
		switch i {
		case 0:
			args = append(args, n.row.Hostname)
		case 1:
			args = append(args, n.row.Bucket)
		case 2:
			args = append(args, n.row.Samples)
		case 3:
			args = append(args, n.row.CpuSum)
		case 4:
			args = append(args, n.row.CpuN)
		case 5:
			args = append(args, n.row.CpuMax.Arg())
		case 6:
			args = append(args, n.row.MemPct.Arg())
		case 7:
			args = append(args, n.row.SwapPct.Arg())
		case 8:
			args = append(args, n.row.Disks.Arg())
		case 9:
			args = append(args, n.row.RxSum)
		case 10:
			args = append(args, n.row.TxSum)
		case 11:
			args = append(args, n.row.NetN)
		case 12:
			args = append(args, n.row.RxMax.Arg())
		case 13:
			args = append(args, n.row.TxMax.Arg())
		}
	}
	var out Row
	rows, err := ex.Query(ctx, st.SQL, args)
	if err != nil {
		return out, err
	}
	defer rows.Close()
	if !rows.Next() {
		if err := rows.Err(); err != nil {
			return out, err
		}
		if n.conflict != 0 && n.conflict%2 == 1 {
			// DO NOTHING suppresses RETURNING, so no row means the row was
			// already there — the success case of an idempotent insert.
			return out, runtime.ErrConflict
		}
		return out, runtime.ErrNoRow
	}
	var sl runtime.Slab
	if err := scan(rows.RawValues(), &out, &sl); err != nil {
		return out, err
	}
	return out, rows.Err()
}

// Inserts reports how many distinct INSERT column sets have compiled.
func Inserts() int { return insCache.Masks() }

// Insert writes one row and reads back every column, so database-computed
// defaults — a generated id, a now() timestamp — land in r rather than
// needing a second SELECT that would race every other writer.
//
// Every insertable column is written, including zero values. storm does
// not treat a zero as 'unset': that guess is why other ORMs cannot insert
// a false, a 0 or an empty string into a column with a default.
func Insert(ctx context.Context, ex runtime.Executor, r *Row) error {
	args := make([]any, 0, 14)
	args = append(args, r.Hostname)
	args = append(args, r.Bucket)
	args = append(args, r.Samples)
	args = append(args, r.CpuSum)
	args = append(args, r.CpuN)
	args = append(args, r.CpuMax.Arg())
	args = append(args, r.MemPct.Arg())
	args = append(args, r.SwapPct.Arg())
	args = append(args, r.Disks.Arg())
	args = append(args, r.RxSum)
	args = append(args, r.TxSum)
	args = append(args, r.NetN)
	args = append(args, r.RxMax.Arg())
	args = append(args, r.TxMax.Arg())
	rows, err := ex.Query(ctx, insertSQL, args)
	if err != nil {
		return err
	}
	defer rows.Close()
	if !rows.Next() {
		if err := rows.Err(); err != nil {
			return err
		}
		return runtime.ErrNoRow
	}
	// The returned strings live as long as this Slab, and the Slab lives
	// as long as r — a Row from an insert owns its own arena, unlike a Row
	// from a scan, which shares the result set's.
	var sl runtime.Slab
	if err := scan(rows.RawValues(), r, &sl); err != nil {
		return err
	}
	return rows.Err()
}

// copyCols is the fixed column list of a bulk load. Unlike Ins there is
// no mask: COPY sends one shape for the whole stream, so every row must
// supply every column and database defaults do not apply. Fill the row
// yourself, or use Create() per row and give up the bulk path.
var copyCols = []string{
	"hostname",
	"bucket",
	"samples",
	"cpu_sum",
	"cpu_n",
	"cpu_max",
	"mem_pct",
	"swap_pct",
	"disks",
	"rx_sum",
	"tx_sum",
	"net_n",
	"rx_max",
	"tx_max",
}

// rowSource walks a []Row for CopyFrom without copying any of it.
type rowSource struct {
	rows []Row
	i    int
	buf  [14]any
}

func (s *rowSource) Next() bool {
	s.i++
	return s.i <= len(s.rows)
}

// Values reuses one buffer across every row, and fills it with POINTERS
// into the caller's slice rather than copies.
//
// Both halves matter. The driver consumes each slice before asking for
// the next, so one buffer is safe. And boxing a pointer into an `any`
// does not allocate while boxing a value does — at a thousand rows that
// is one allocation per column per row, or none. Measured: the first cut
// boxed values and cost 7 allocations per row.
func (s *rowSource) Values() []any {
	r := &s.rows[s.i-1]
	s.buf[0] = &r.Hostname
	s.buf[1] = &r.Bucket
	s.buf[2] = &r.Samples
	s.buf[3] = &r.CpuSum
	s.buf[4] = &r.CpuN
	s.buf[5] = r.CpuMax.Ptr()
	s.buf[6] = r.MemPct.Ptr()
	s.buf[7] = r.SwapPct.Ptr()
	s.buf[8] = r.Disks.Ptr()
	s.buf[9] = &r.RxSum
	s.buf[10] = &r.TxSum
	s.buf[11] = &r.NetN
	s.buf[12] = r.RxMax.Ptr()
	s.buf[13] = r.TxMax.Ptr()
	return s.buf[:]
}

func (s *rowSource) Err() error { return nil }

// InsertAll bulk-loads rows through the driver's COPY protocol: ONE round
// trip regardless of row count, because COPY is a different wire path and
// not a faster loop over INSERT.
//
// It returns no rows. COPY has no RETURNING, so a caller who needs
// database-generated ids must supply them — which is why the primary key
// is in copyCols and must be set on every row.
func InsertAll(ctx context.Context, ex runtime.Executor, rows []Row) (int64, error) {
	if len(rows) == 0 {
		return 0, nil
	}
	src := &rowSource{rows: rows}
	return ex.CopyFrom(ctx, "usage_history", copyCols, src)
}

// InsertOp is an insert as a queueable statement. It writes every
// insertable column, because a batch of a thousand rows that each chose
// a different column set would compile a thousand statements and defeat
// the point of batching them.
//
// WantRows is false: a batched insert reports a count. Asking for
// RETURNING here would mean scanning a result per statement, which is
// exactly the per-row work a batch exists to avoid.
func InsertOp(r Row) runtime.BatchOp {
	var mask uint64
	mask |= 1 << 0
	mask |= 1 << 1
	mask |= 1 << 2
	mask |= 1 << 3
	mask |= 1 << 4
	mask |= 1 << 5
	mask |= 1 << 6
	mask |= 1 << 7
	mask |= 1 << 8
	mask |= 1 << 9
	mask |= 1 << 10
	mask |= 1 << 11
	mask |= 1 << 12
	mask |= 1 << 13
	st := stmtForInsertNoReturn(mask, 0, 0)
	args := make([]any, 0, 14)
	args = append(args, r.Hostname)
	args = append(args, r.Bucket)
	args = append(args, r.Samples)
	args = append(args, r.CpuSum)
	args = append(args, r.CpuN)
	args = append(args, r.CpuMax.Arg())
	args = append(args, r.MemPct.Arg())
	args = append(args, r.SwapPct.Arg())
	args = append(args, r.Disks.Arg())
	args = append(args, r.RxSum)
	args = append(args, r.TxSum)
	args = append(args, r.NetN)
	args = append(args, r.RxMax.Arg())
	args = append(args, r.TxMax.Arg())
	return runtime.BatchOp{SQL: st.SQL, Args: args}
}

// Op is this Ins as a queueable statement, conflict clause and all —
// the bulk upsert.
//
// InsertOp above takes a Row and writes every column, so a thousand of
// them share one statement. This takes the BUILDER, so it carries the
// mask and the ON CONFLICT the caller chose: ingesting a batch that
// should overwrite what is already there, or skip it, needs both and
// could otherwise only be done one round trip at a time.
//
// One statement per distinct (mask, conflict) pair, cached like every
// other. Assign the same columns on every row of a batch and it stays
// one; vary them and it is one per shape, which is the cost of asking.
//
// WantRows is false, as for InsertOp: a batch reports counts. A DO
// NOTHING that skipped a row is a zero in that count — the batch
// cannot say which rows were skipped, only how many.
func (n *Ins) Op() (runtime.BatchOp, error) {
	if n.set == 0 {
		return runtime.BatchOp{}, runtime.ErrNothingAssigned
	}
	st := stmtForInsertNoReturn(n.set, n.conflict, n.add)
	if st.Err != nil {
		return runtime.BatchOp{}, st.Err
	}
	args := make([]any, 0, st.NArg)
	for i := 0; i < nInsertable; i++ {
		if n.set&(1<<uint(i)) == 0 {
			continue
		}
		switch i {
		case 0:
			args = append(args, n.row.Hostname)
		case 1:
			args = append(args, n.row.Bucket)
		case 2:
			args = append(args, n.row.Samples)
		case 3:
			args = append(args, n.row.CpuSum)
		case 4:
			args = append(args, n.row.CpuN)
		case 5:
			args = append(args, n.row.CpuMax.Arg())
		case 6:
			args = append(args, n.row.MemPct.Arg())
		case 7:
			args = append(args, n.row.SwapPct.Arg())
		case 8:
			args = append(args, n.row.Disks.Arg())
		case 9:
			args = append(args, n.row.RxSum)
		case 10:
			args = append(args, n.row.TxSum)
		case 11:
			args = append(args, n.row.NetN)
		case 12:
			args = append(args, n.row.RxMax.Arg())
		case 13:
			args = append(args, n.row.TxMax.Arg())
		}
	}
	return runtime.BatchOp{SQL: st.SQL, Args: args}, nil
}

// stmtForInsertNoReturn is stmtForInsert without RETURNING, for the
// batch path. Its own cache: the two differ by a suffix, and sharing
// one would hand a batch the statement that asks for rows back.
func stmtForInsertNoReturn(mask uint64, conflict uint8, add uint64) *runtime.Stmt {
	// The conflict clause is part of the statement, so it must be part of
	// the key. Packing it above the column bits keeps one cache for both.
	key := mask | uint64(conflict)<<nInsertable
	// Accumulating only means something in a DO UPDATE (an even code
	// from 2): anywhere else it is an ordinary insert of the value, and
	// keying it apart would compile the same statement twice.
	if conflict < 2 || conflict%2 == 1 {
		add = 0
	}
	add &= mask
	if st := insOpCache.Get(runtime.MaskKey{Dirty: key, Expr: add}); st != nil {
		return st
	}
	cols := make([]string, 0, nInsertable)
	for i := 0; i < nInsertable; i++ {
		if mask&(1<<uint(i)) != 0 {
			cols = append(cols, insCols[i])
		}
	}
	suffix := ""
	if conflict > 0 {
		suffix = upsertTail(conflict, mask, add)
	}
	return insOpCache.Put(runtime.MaskKey{Dirty: key, Expr: add}, runtime.SpliceInsertWith(insPrefix, insParts, cols, insPlaceholder, suffix))
}

// UpdateOp is this Mut's update as a queueable statement.
//
// The optimistic lock still applies, but the caller must check the
// affected count the batch reports: a stale write inside a batch is not
// an error the driver raises, it is a zero the caller has to notice.
//
// A server-side assignment is queued like any other, but the staged row
// is NOT refreshed: a batch reports counts, not rows. Use Update when
// the computed value is the thing you need.
func (m *Mut) UpdateOp() (runtime.BatchOp, bool) {
	if m.dirty == 0 && m.expr == 0 {
		return runtime.BatchOp{}, false
	}
	st := stmtForKey(m.key(), false)
	args := make([]any, 0, st.NArg)
	for i := 0; i < nUpdatable; i++ {
		if m.dirty&(1<<uint(i)) == 0 {
			continue
		}
		switch i {
		case 0:
			args = append(args, m.row.Samples)
		case 1:
			args = append(args, m.row.CpuSum)
		case 2:
			args = append(args, m.row.CpuN)
		case 3:
			args = append(args, m.row.CpuMax.Arg())
		case 4:
			args = append(args, m.row.MemPct.Arg())
		case 5:
			args = append(args, m.row.SwapPct.Arg())
		case 6:
			args = append(args, m.row.Disks.Arg())
		case 7:
			args = append(args, m.row.RxSum)
		case 8:
			args = append(args, m.row.TxSum)
		case 9:
			args = append(args, m.row.NetN)
		case 10:
			args = append(args, m.row.RxMax.Arg())
		case 11:
			args = append(args, m.row.TxMax.Arg())
		}
	}
	args = append(args, m.row.Hostname)
	args = append(args, m.row.Bucket)
	return runtime.BatchOp{SQL: st.SQL, Args: args}, true
}

// DeleteOp is a delete as a queueable statement.
func DeleteOp(hostname string, bucket time.Time) runtime.BatchOp {
	return runtime.BatchOp{SQL: deleteSQL, Args: []any{hostname, bucket}}
}

// Table is the table these statements write, so a Unit can order a mixed
// batch by foreign key without knowing what any of them are.
const Table = "usage_history"

// stmtForKey compiles the UPDATE for one (dirty, expr) pair, once.
//
// The pair is the identity, not the dirty mask alone: the same column
// assigned a bound value and assigned a server-side expression are two
// different statements, and the arguments of one do not fit the other.
//
// ret picks the cache as well as the suffix. The batch path passes
// false — it cannot read rows back, so it must not ask for them.
func stmtForKey(k runtime.MaskKey, ret bool) *runtime.Stmt {
	cache := updCache
	if !ret {
		cache = updOpCache
	}
	if st := cache.Get(k); st != nil {
		return st
	}
	set := make([]runtime.Frag, 0, nUpdatable+1)
	for i := 0; i < nUpdatable; i++ {
		// An expression wins: a column set both ways cannot happen,
		// because each setter clears the other's bit.
		switch {
		case k.Expr&(1<<uint(i)) != 0:
			set = append(set, exprFrags[i])
		case k.Dirty&(1<<uint(i)) != 0:
			set = append(set, setFrags[i])
		}
	}
	where := make([]runtime.Frag, 0, 3)
	where = append(where, pkFrags[:]...)
	// Only an expression needs reading back. A plain UPDATE already
	// knows every value it wrote, so it pays no RETURNING.
	suffix := ""
	if ret && k.Expr != 0 {
		suffix = updReturning
	}
	return cache.Put(k, runtime.SpliceSections(updatePrefix, []runtime.Section{
		{Lead: "", Sep: ", ", Frags: set},
		{Lead: " WHERE ", Sep: " AND ", Frags: where},
	}, suffix))
}

// Update writes the assigned columns of one row.
//
// Assigning nothing is not an error and issues no statement — an UPDATE
// with an empty SET list is not valid SQL, and a caller looping over
// possibly-changed fields should not have to special-case the empty case.
//
// An assignment the DATABASE computes is read back in the same
// statement, so m.Row() is the row that now exists rather than the
// one that used to. A second SELECT would race every other writer,
// which is the same reason Insert reads its row back.
func (m *Mut) Update(ctx context.Context, ex runtime.Executor) error {
	if m.dirty == 0 && m.expr == 0 {
		return nil
	}
	st := stmtForKey(m.key(), true)
	if st.Err != nil {
		// A malformed token stream is a code-generation bug. Executing it
		// would run a query whose filter is not the one that was asked for.
		return st.Err
	}
	args := make([]any, 0, st.NArg)
	for i := 0; i < nUpdatable; i++ {
		if m.dirty&(1<<uint(i)) == 0 {
			continue
		}
		switch i {
		case 0:
			args = append(args, m.row.Samples)
		case 1:
			args = append(args, m.row.CpuSum)
		case 2:
			args = append(args, m.row.CpuN)
		case 3:
			args = append(args, m.row.CpuMax.Arg())
		case 4:
			args = append(args, m.row.MemPct.Arg())
		case 5:
			args = append(args, m.row.SwapPct.Arg())
		case 6:
			args = append(args, m.row.Disks.Arg())
		case 7:
			args = append(args, m.row.RxSum)
		case 8:
			args = append(args, m.row.TxSum)
		case 9:
			args = append(args, m.row.NetN)
		case 10:
			args = append(args, m.row.RxMax.Arg())
		case 11:
			args = append(args, m.row.TxMax.Arg())
		}
	}
	args = append(args, m.row.Hostname)
	args = append(args, m.row.Bucket)
	if m.expr != 0 {
		return m.updateReturning(ctx, ex, st, args)
	}
	n, err := ex.Exec(ctx, st.SQL, args)
	if err != nil {
		return err
	}
	if n == 0 {
		return runtime.ErrNoRow
	}
	m.dirty = 0
	m.expr = 0
	return nil
}

// updateReturning runs an UPDATE that let the database compute part of
// the row, and reads the whole row back into the staged copy.
//
// Every column, not just the computed ones: a trigger may have touched
// anything, and a staged row that is fresh in two fields and stale in
// the rest is harder to reason about than one that is simply current.
func (m *Mut) updateReturning(ctx context.Context, ex runtime.Executor, st *runtime.Stmt, args []any) error {
	rows, err := ex.Query(ctx, st.SQL, args)
	if err != nil {
		return err
	}
	defer rows.Close()
	if !rows.Next() {
		if err := rows.Err(); err != nil {
			return err
		}
		return runtime.ErrNoRow
	}
	// The staged row owns this arena, the way an inserted row does.
	var sl runtime.Slab
	if err := scan(rows.RawValues(), &m.row, &sl); err != nil {
		return err
	}
	if err := rows.Err(); err != nil {
		return err
	}
	m.dirty = 0
	m.expr = 0
	return nil
}

var deleteSQL = runtime.SpliceSections(deletePrefix, []runtime.Section{
	{Lead: " WHERE ", Sep: " AND ", Frags: pkFrags[:]},
}, "").SQL

// Delete removes one row by primary key. A row that was already gone is
// runtime.ErrNoRow, not success: a caller deleting something that is not
// there usually has a bug, and swallowing it hides the bug.
func Delete(ctx context.Context, ex runtime.Executor, hostname string, bucket time.Time) error {
	n, err := ex.Exec(ctx, deleteSQL, []any{hostname, bucket})
	if err != nil {
		return err
	}
	if n == 0 {
		return runtime.ErrNoRow
	}
	return nil
}

// Set-based writes. Two caches of their own, keyed like the read
// caches by the predicate stream — UpdateAll's prefixed with the
// assignment masks, which are as much its identity as the predicates.
var (
	updAllCache = runtime.NewTreeCache()
	delAllCache = runtime.NewTreeCache()
)

// writeAllErr is what UpdateAll and DeleteAll refuse.
func (q Query) writeAllErr() error {
	if err := q.Err(); err != nil {
		return err
	}
	if q.nt == 0 {
		return runtime.ErrUnfilteredWrite
	}
	if q.limit != 1000 || q.offset != 0 || q.lock != 0 {
		return runtime.ErrPagedWrite
	}
	return nil
}

// updAllStmtFor compiles one (assignments, predicates) pair, once.
func updAllStmtFor(k runtime.MaskKey, preds []runtime.Tok) *runtime.Stmt {
	var key [25]runtime.Tok
	key[0], key[1] = runtime.Tok(k.Dirty), runtime.Tok(k.Dirty>>32)
	key[2], key[3] = runtime.Tok(k.Expr), runtime.Tok(k.Expr>>32)
	n := 4 + copy(key[4:], preds)
	if st := updAllCache.Get(key[:n]); st != nil {
		return st
	}
	set := make([]runtime.Frag, 0, nUpdatable+1)
	for i := 0; i < nUpdatable; i++ {
		switch {
		case k.Expr&(1<<uint(i)) != 0:
			set = append(set, exprFrags[i])
		case k.Dirty&(1<<uint(i)) != 0:
			set = append(set, setFrags[i])
		}
	}
	head := runtime.SpliceSections(updatePrefix, []runtime.Section{
		{Lead: "", Sep: ", ", Frags: set},
	}, "")
	if head.Err != nil {
		return head
	}
	return updAllCache.Put(key[:n], runtime.SpliceTreeFrom(head.SQL, preds, lowering, "", head.NArg))
}

// UpdateAll writes m's assigned columns to every row the query
// matches, in ONE statement, and reports how many it wrote:
//
//	var m Mut
//	m.Set…(v)            // bound values and server-side forms alike
//	n, err := New().Where(…).UpdateAll(ctx, ex, m)
//
// Only assigned columns are written, as for Update; nothing assigned
// issues no statement and reports 0. The query must have a predicate —
// runtime.ErrUnfilteredWrite otherwise — and must not carry Limit,
// Offset or a row lock, which a set-based UPDATE has no clause for:
// runtime.ErrPagedWrite. Order is ignored, as it is by Count.
func (q Query) UpdateAll(ctx context.Context, ex runtime.Executor, m Mut) (int64, error) {
	if err := q.writeAllErr(); err != nil {
		return 0, err
	}
	if m.dirty == 0 && m.expr == 0 {
		return 0, nil
	}
	var buf [21]runtime.Tok
	st := updAllStmtFor(m.key(), q.preds(&buf))
	if st.Err != nil {
		return 0, st.Err
	}
	b := binders.Get()
	defer putBinder(b)
	args := make([]any, 0, st.NArg)
	for i := 0; i < nUpdatable; i++ {
		if m.dirty&(1<<uint(i)) == 0 {
			continue
		}
		switch i {
		case 0:
			args = append(args, m.row.Samples)
		case 1:
			args = append(args, m.row.CpuSum)
		case 2:
			args = append(args, m.row.CpuN)
		case 3:
			args = append(args, m.row.CpuMax.Arg())
		case 4:
			args = append(args, m.row.MemPct.Arg())
		case 5:
			args = append(args, m.row.SwapPct.Arg())
		case 6:
			args = append(args, m.row.Disks.Arg())
		case 7:
			args = append(args, m.row.RxSum)
		case 8:
			args = append(args, m.row.TxSum)
		case 9:
			args = append(args, m.row.NetN)
		case 10:
			args = append(args, m.row.RxMax.Arg())
		case 11:
			args = append(args, m.row.TxMax.Arg())
		}
	}
	args = append(args, q.bindPreds(b)...)
	return ex.Exec(ctx, st.SQL, args)
}

func delAllStmtFor(toks []runtime.Tok) *runtime.Stmt {
	if st := delAllCache.Get(toks); st != nil {
		return st
	}
	return delAllCache.Put(toks, runtime.SpliceTree(deletePrefix, toks, lowering, ""))
}

// DeleteAll removes every row the query matches, in ONE statement,
// and reports how many it removed.
//
// The query must have a predicate — runtime.ErrUnfilteredWrite
// otherwise — and must not carry Limit, Offset or a row lock:
// runtime.ErrPagedWrite. Order is ignored, as it is by Count.
func (q Query) DeleteAll(ctx context.Context, ex runtime.Executor) (int64, error) {
	if err := q.writeAllErr(); err != nil {
		return 0, err
	}
	var buf [21]runtime.Tok
	st := delAllStmtFor(q.preds(&buf))
	if st.Err != nil {
		return 0, st.Err
	}
	b := binders.Get()
	defer putBinder(b)
	return ex.Exec(ctx, st.SQL, q.bindPreds(b))
}
